<section class="section-heading"><div><h2>A welcoming starting point</h2><p>Each starter uses this grid’s name, branding and native Member Login. Built-ins cannot be overwritten.</p></div></section><div class="theme-grid"><?php foreach(ag_sd_starters() as $id=>$starter):?><article class="theme-card"><div class="theme-picture"><?=ag_sd_visual_card(ag_sa_presets()[$starter['theme']],$starter['name'],'public',$id)?></div><div class="theme-copy"><span class="step">PROTECTED STARTER</span><h3><?=ag_h($starter['name'])?></h3><p><?=ag_h($starter['text'])?></p><button type="button" class="secondary preview-design" data-url="/Other/site-front-preview.php?starter=<?=ag_h($id)?>">Preview</button><form method="post"><?php $hidden('starter_create')?><input type="hidden" name="starter" value="<?=ag_h($id)?>"><label>Your design name<input name="name" value="<?=ag_h($starter['name'].' copy')?>" required maxlength="120"></label><button>Duplicate as private draft</button></form></div></article><?php endforeach ?></div>
